private static void HandleBaseCss(HttpContext context)
{
    SessionUser user = RequireLogin(context);
    if (user == null) return;

    string css = LoadBundledBaseCss(context);
    Dictionary<string, object> data = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
    data["BaseCss"] = css ?? string.Empty;
    WriteJson(context, true, "OK", data);
}

private static string LoadBundledBaseCss(HttpContext context)
{
    if (context == null) return string.Empty;

    string path = context.Server.MapPath("~/Controls/3Landing/TiemChung/tiem-chung-page-base.css.inc");
    if (!File.Exists(path)) return string.Empty;

    try
    {
        return File.ReadAllText(path, Encoding.UTF8);
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("TiemChungPageHandler basecss: " + ex);
        return string.Empty;
    }
}

