function hasEditorContent() {
    if (!editor) return false;

    var wrapper = editor.getWrapper();
    var roots = wrapper.find('.tiem-chung-page');
    if (!roots || !roots.length) return false;

    var body = wrapper.find('.tiem-chung-page-body');
    var container = body && body.length ? body[0] : roots[0];
    var children = container.components ? container.components() : null;
    if (children && children.length) return true;

    var doc = getCanvasDocument();
    if (!doc) return false;
    var root = doc.querySelector('.tiem-chung-page');
    if (!root) return false;
    var text = String(root.textContent || '').replace(/\s+/g, ' ').trim();
    return text.length >= 20;
}

function applyEditorHtml(html, language) {
    editor.setComponents(ensureShell(html || emptyTemplate(language)));
    editor.setStyle(state.css || '');
}

function refreshEditorCanvas() {
    if (!editor) return;
    try { editor.refresh(); } catch (ignore) { }
    injectBaseCss();
    protectShell();
    revealEditorContent();
    bindCanvasInteractions(true);
}

function loadLanguage(language) {
    if (!editor) return;
    var dirtyBeforeLoad = dirty;
    hydrating = true;
    currentLanguage = language;
    var item = state[language];
    var loaded = false;

    try {
        if (item.project) {
            try {
                editor.loadProjectData(JSON.parse(item.project));
                loaded = hasEditorContent();
            } catch (ignore) { loaded = false; }
        }
        if (!loaded) {
            applyEditorHtml(item.html, language);
            item.project = '';
        } else {
            editor.setStyle(state.css || '');
        }
        refreshEditorCanvas();
        updateComponentInspector(null);
        languageVisited[language] = true;
    } catch (error) {
        try {
            applyEditorHtml(item.html, language);
            item.project = '';
            refreshEditorCanvas();
            updateComponentInspector(null);
            languageVisited[language] = true;
            toast('Project JSON lỗi; đã nạp lại HTML từ CMS.', false);
        } catch (innerError) {
            toast('Không tải được nội dung editor: ' + (innerError && innerError.message ? innerError.message : 'lỗi không xác định'), false);
        }
    }

    dirty = dirtyBeforeLoad;
    updateFlow();
    window.setTimeout(function () {
        hydrating = false;
        dirty = dirtyBeforeLoad;
        refreshEditorCanvas();
        updateFlow();
    }, 120);
}

