function readBundledBaseCss() {
    return new Promise(function (resolve, reject) {
        if (!handlerUrl) {
            reject(new Error('Thiếu handler CMS.'));
            return;
        }

        requestJson(handlerUrl + '?action=basecss', 'GET', null, function (response, status) {
            if (status === 0 || !response || !response.Success) {
                reject(new Error((response && response.Message) ? response.Message : 'Không tải được CSS gốc.'));
                return;
            }
            var data = response.Data || {};
            resolve(data.BaseCss || data.baseCss || '');
        });
    });
}

function loadBaseCssOnly() {
    return readBundledBaseCss().then(function (css) {
        if (css) {
            baseCss = css;
            injectBaseCss();
            return;
        }
        throw new Error('CSS gốc trống.');
    }).catch(function () {
        var sourceUrl = (el('abSourceUrl').value || defaultSourceUrl).trim();
        if (!sourceUrl) return;
        return readFrontend(sourceUrl, 1).then(function (page) {
            baseCss = page.baseCss || baseCss;
            injectBaseCss();
        }).catch(function () { });
    });
}

